'use strict';
/*
  سيرفر التحكم بالتطبيق لكل مستخدم على حدة.

  واجهتان:
    POST /api/check  (التطبيق)       { code, device, version }  ->  { ok, message }
    POST /api/admin  (لوحة التحكم)   { key, action, data }      ->  { ok, ... }
        actions: list | save | reset | delete | bulk | config | log

  متغيرات البيئة:
    ADMIN_KEY     كلمة سر الإدارة الكاملة (إجبارية)
    VIEWER_KEY    كلمة سر إضافية اختيارية، للعرض فقط دون تعديل (اختياري)
    DATABASE_URL  رابط Postgres (اختياري - موصى به على Render المجاني لأن الملفات تُمسح)
    DATA_FILE     مسار ملف JSON عند عدم وجود DATABASE_URL (الافتراضي ./data.json)
    PORT          المنفذ (Render يضبطه تلقائياً)
*/
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
/* لوحة التحكم مضمَّنة هنا، فلا تعتمد على ملف admin.html المنفصل */
const ADMIN_HTML = Buffer.from('', 'base64').toString('utf8');

const ADMIN_KEY = process.env.ADMIN_KEY || '';
const VIEWER_KEY = process.env.VIEWER_KEY || '';
if (!ADMIN_KEY) {
  console.error('ADMIN_KEY غير مضبوط. اضبطه في متغيرات البيئة.');
  process.exit(1);
}

/* ---------------- التخزين ----------------
   حالة واحدة: { config: {...}, licenses: { CODE: {...} }, log: [...] }
   تُحفظ إما في Postgres (صف واحد) أو في ملف JSON. */
const DEFAULT_STATE = () => ({
  config: { enabled: true, message: '', min_version: '', msg_ts: 0 },
  licenses: {},
  log: [],
  auth: { adminKey: null, viewerKey: null },
  userdata: {},
  sharedNames: { rev: 0, list: '[]' },
  encDevices: {}
});

function makeFileStore(file) {
  return {
    kind: 'file',
    async init() {},
    async load() {
      try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch (e) { return null; }
    },
    async save(state) {
      const tmp = file + '.tmp';
      fs.writeFileSync(tmp, JSON.stringify(state));
      fs.renameSync(tmp, file);
    }
  };
}

function makePgStore(url) {
  const { Pool } = require('pg');
  const local = /localhost|127\.0\.0\.1/.test(url);
  /* التحقق من شهادة القاعدة مفعّل افتراضياً (أأمن). إن فشل الاتصال بعد هذا التغيير بسبب
     شهادة الخادم (نادر مع Supabase)، اضبط DB_SSL_INSECURE=true في متغيرات البيئة مؤقتاً. */
  const insecure = process.env.DB_SSL_INSECURE === 'true';
  const pool = new Pool({
    connectionString: url,
    ssl: local ? false : { rejectUnauthorized: !insecure },
    max: 3
  });
  return {
    kind: 'postgres',
    async init() {
      await pool.query('CREATE TABLE IF NOT EXISTS app_state (id INT PRIMARY KEY, data JSONB NOT NULL)');
      /* مهم في Supabase: تفعيل RLS بدون أي سياسة يمنع قراءة هذا الجدول (رموز المستخدمين)
         عبر المفتاح العام sb_publishable. السيرفر يتصل مباشرة بصلاحية مالك الجدول فلا يتأثر. */
      await pool.query('ALTER TABLE app_state ENABLE ROW LEVEL SECURITY');
    },
    async load() {
      const r = await pool.query('SELECT data FROM app_state WHERE id = 1');
      return r.rows[0] ? r.rows[0].data : null;
    },
    async save(state) {
      await pool.query(
        'INSERT INTO app_state (id, data) VALUES (1, $1) ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data',
        [JSON.stringify(state)]
      );
    }
  };
}

const store = process.env.DATABASE_URL
  ? makePgStore(process.env.DATABASE_URL)
  : makeFileStore(process.env.DATA_FILE || path.join(__dirname, 'data.json'));

let STATE = DEFAULT_STATE();

/* كل التعديلات تمر بطابور واحد لمنع تضارب الكتابة */
let queue = Promise.resolve();
function mutate(fn) {
  const run = queue.then(async () => {
    const before = JSON.stringify(STATE);
    let result;
    try {
      result = await fn(STATE);
      await store.save(STATE);
    } catch (e) {
      STATE = JSON.parse(before); // تراجع إن فشل الحفظ
      throw e;
    }
    return result;
  });
  queue = run.catch(() => {});
  return run;
}

function logAction(s, action, code, by) {
  if (!Array.isArray(s.log)) s.log = [];
  s.log.push({ t: Date.now(), action, code: code || '', by: by || 'admin' });
  if (s.log.length > 300) s.log.splice(0, s.log.length - 300);
}

/* ---------------- أدوات ---------------- */
const normCode = (c) => String(c || '').trim().toUpperCase();
const str = (v, max) => String(v == null ? '' : v).slice(0, max);

function cmpVersion(a, b) {
  const pa = String(a || '0').split('.').map((x) => parseInt(x, 10) || 0);
  const pb = String(b || '0').split('.').map((x) => parseInt(x, 10) || 0);
  for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d) return d;
  }
  return 0;
}

/* معرّف الرسالة المنبثقة: يتغير عند تغيير نص الرسالة أو عند "إعادة إرسال"،
   والتطبيق يعرض كل رسالة مرة واحدة فقط لكل معرّف جديد. */
function msgId(scope, text, ts) {
  return crypto.createHash('sha1').update(scope + '|' + text + '|' + (ts || 0)).digest('hex').slice(0, 12);
}

/* آخر نبضة مزامنة لكل رمز (في الذاكرة فقط، لإظهار "متصل الآن" في اللوحة) */
const PINGS = new Map();
/* رموز معاينة قصيرة العمر تصدرها اللوحة لفتح التطبيق من داخلها */
const PREVIEW = new Map();
const ONLINE_MS = 45 * 1000;

/* ---- مزامنة بيانات التطبيق (ثنائية الاتجاه) ----
   لكل رمز نسخة: { rev, keys:{ مفتاح: قيمة } }. العميل (جهاز المستخدم أو معاينة اللوحة) يرسل
   تغييراته فقط {k:قيمة|null} مع آخر rev يعرفه؛ إن كان متأخراً يردّ السيرفر بالنسخة الكاملة. */
const SYNC_KEYS = ['saved-names-v1', 'acct-balance-v2', 'tx-history-v1', 'shared-names-v1']; // الضبط + تفاصيل الحساب + المعاملات + القاعدة المخفية

let flushT = null;
function scheduleFlush() {
  if (flushT) return;
  flushT = setTimeout(() => { flushT = null; mutate(() => {}).catch((e) => console.error('flush', e)); }, 15000);
}
/* تجميع أحادي الاتجاه: ما يضيفه أي مستخدم في شاشة "الضبط" عنده يُجمَّع هنا ليظهر للإدارة فقط،
   ولا يُعاد إرساله لأي مستخدم آخر (قاعدة البيانات المشتركة صارت للعرض والتنظيم عند الإدارة فقط). */
function aggregateUserNames(code, ud) {
  let own = [];
  try { own = JSON.parse(ud.keys['saved-names-v1'] || '[]'); if (!Array.isArray(own)) own = []; } catch (e) { own = []; }
  if (!own.length) return;
  if (!STATE.sharedNames) STATE.sharedNames = { rev: 0, list: '[]' };
  let shared = [];
  try { shared = JSON.parse(STATE.sharedNames.list || '[]'); if (!Array.isArray(shared)) shared = []; } catch (e) { shared = []; }
  const map = new Map();
  shared.forEach((x) => { if (x && x.num) map.set(String(x.num), x); });
  let changed = false;
  own.forEach((x) => {
    if (!x || !x.num) return;
    const k = String(x.num);
    const prev = map.get(k);
    const next = { num: str(x.num, 20), name: str(x.name, 80), type: str(x.type, 40), branch: str(x.branch, 40), from: code };
    if (!prev || prev.name !== next.name || prev.type !== next.type || prev.branch !== next.branch || prev.from !== code) {
      map.set(k, next); changed = true;
    }
  });
  if (changed) { STATE.sharedNames.list = JSON.stringify(Array.from(map.values())); STATE.sharedNames.rev++; }
}
/* ينشر القائمة المجمّعة كاملة (أرقام المستخدمين + ما تضيفه الإدارة) في مفتاح منفصل مخفي
   لا تعرضه شاشة "الضبط"، فتعمل الأرقام في التحويل لكل المستخدمين دون أن تظهر عندهم ظاهرياً. */
function pushSharedDown(ud) {
  if (!STATE.sharedNames) STATE.sharedNames = { rev: 0, list: '[]' };
  if (ud.appliedSharedRev === STATE.sharedNames.rev) return false;
  ud.keys['shared-names-v1'] = STATE.sharedNames.list;
  ud.appliedSharedRev = STATE.sharedNames.rev;
  return true;
}
/* دمج قائمة أرقام 'الضبط' دون حذف: أي رقم محفوظ سابقاً على السيرفر يبقى، حتى لو حذفه
   المستخدم محلياً وأرسل قائمة أقصر. التحديث على نفس الرقم (تغيير الاسم مثلاً) مسموح. */
function mergeSavedNames(oldStr, newStr) {
  let oldArr = [], newArr = [];
  try { oldArr = JSON.parse(oldStr || '[]'); if (!Array.isArray(oldArr)) oldArr = []; } catch (e) { oldArr = []; }
  try { newArr = JSON.parse(newStr || '[]'); if (!Array.isArray(newArr)) newArr = []; } catch (e) { return oldStr; }
  const map = new Map();
  oldArr.forEach((x) => { if (x && x.num != null) map.set(String(x.num), x); });
  newArr.forEach((x) => { if (x && x.num != null) map.set(String(x.num), x); });
  return JSON.stringify(Array.from(map.values()));
}

function syncData(code, body, lic) {
  if (lic && lic.sync === false) return { nosync: true };
  if (!STATE.userdata) STATE.userdata = {};
  if (!STATE.sharedNames) STATE.sharedNames = { rev: 0, list: '[]' };
  const ud = STATE.userdata[code] || (STATE.userdata[code] = { rev: 0, keys: {} });
  if (!ud.lastChanged) ud.lastChanged = {};
  const before = ud.rev;
  const ch = body.changes && typeof body.changes === 'object' ? body.changes : {};
  let n = 0, size = 0;
  Object.keys(ud.keys).forEach((k) => { size += k.length + ud.keys[k].length; });
  Object.keys(ch).slice(0, 500).forEach((k) => {
    if (k.length > 200) return;
    const v = ch[k];
    if (k === 'saved-names-v1') {
      /* لا تُحذف هذه القائمة إطلاقاً، ادمج فقط */
      const merged = mergeSavedNames(ud.keys[k], v === null ? '[]' : String(v));
      if (merged.length > 100000 || size + merged.length > 450000) return;
      if (ud.keys[k] !== merged) { size += merged.length - (ud.keys[k] ? ud.keys[k].length : -k.length); ud.keys[k] = merged; n++; ud.lastChanged[k] = Date.now(); }
      return;
    }
    if (v === null) { if (k in ud.keys) { size -= k.length + ud.keys[k].length; delete ud.keys[k]; n++; ud.lastChanged[k] = Date.now(); } return; }
    const sv = String(v);
    if (sv.length > 100000 || size + sv.length > 450000) return;
    if (ud.keys[k] !== sv) { size += sv.length - (ud.keys[k] ? ud.keys[k].length : -k.length); ud.keys[k] = sv; n++; ud.lastChanged[k] = Date.now(); }
  });
  aggregateUserNames(code, ud);        // ما يضيفه هذا المستخدم -> يظهر للإدارة فوراً
  const sharedPushed = pushSharedDown(ud);   // القاعدة (أرقام المستخدمين + الإدارة) -> كل مستخدم، مخفية
  if (n || sharedPushed) { ud.rev++; scheduleFlush(); }
  const out = { rev: ud.rev };
  if (Number(body.rev) !== before || sharedPushed) out.full = ud.keys;   // العميل متأخر أو وصلته أرقام جديدة
  return out;
}

/* تاريخ "YYYY-MM-DD" -> نهاية ذلك اليوم بالمللي ثانية، أو null */
function parseExpiry(v) {
  const s = String(v || '').trim();
  if (!s) return null;
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return null;
  const d = new Date(+m[1], +m[2] - 1, +m[3], 23, 59, 59);
  const t = d.getTime();
  return Number.isFinite(t) ? t : null;
}

function safeEqual(a, b) {
  if (!a || !b) return false;
  const ha = crypto.createHash('sha256').update(String(a)).digest();
  const hb = crypto.createHash('sha256').update(String(b)).digest();
  return crypto.timingSafeEqual(ha, hb);
}

/* كلمة سر الإدارة في متغيرات البيئة (ADMIN_KEY) تبقى صالحة دائماً كمفتاح استرجاع طوارئ،
   حتى لو غيّر المدير كلمة السر من داخل اللوحة. */
function currentAdminKey() {
  const a = STATE.auth || {};
  return typeof a.adminKey === 'string' && a.adminKey ? a.adminKey : null;
}
function currentViewerKey() {
  const a = STATE.auth || {};
  if (a.viewerKey === '') return ''; // عُطِّل الدخول للعرض عمداً من اللوحة
  return typeof a.viewerKey === 'string' && a.viewerKey ? a.viewerKey : (VIEWER_KEY || '');
}

/* تحديد دور صاحب الطلب: admin (تحكم كامل) أو viewer (عرض فقط) أو لا شيء */
function resolveRole(key) {
  if (safeEqual(key, ADMIN_KEY)) return 'admin'; // مفتاح الطوارئ من Render، يعمل دائماً
  const a2 = currentAdminKey();
  if (a2 && safeEqual(key, a2)) return 'admin'; // كلمة السر الحالية المُغيَّرة من اللوحة
  const v = currentViewerKey();
  if (v && safeEqual(key, v)) return 'viewer';
  return null;
}

/* تحديد المحاولات الفاشلة لكل IP */
function makeLimiter(maxFails, windowMs) {
  const m = new Map();
  return {
    blocked(ip) {
      const e = m.get(ip);
      if (!e) return false;
      if (Date.now() - e.t > windowMs) { m.delete(ip); return false; }
      return e.n >= maxFails;
    },
    fail(ip) {
      const e = m.get(ip);
      if (!e || Date.now() - e.t > windowMs) m.set(ip, { n: 1, t: Date.now() });
      else e.n++;
    },
    reset(ip) { m.delete(ip); }
  };
}
/* حماية من التخمين الموزّع: كلما زادت المحاولات الفاشلة (من أي مصدر) يتباطأ الرد على الخاطئ فقط */
const GFAIL = [];
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function failDelay() {
  const now = Date.now();
  GFAIL.push(now);
  while (GFAIL.length && now - GFAIL[0] > 60000) GFAIL.shift();
  await sleep(Math.min(400 + GFAIL.length * 150, 5000));
}
/* سجل محاولات دخول اللوحة الخاطئة (بالذاكرة فقط)، لعرض تنبيه داخل اللوحة نفسها عند فتحها. */
const ADMIN_FAILS = [];
function noteAdminFail() {
  const now = Date.now();
  ADMIN_FAILS.push(now);
  while (ADMIN_FAILS.length && now - ADMIN_FAILS[0] > 60 * 60 * 1000) ADMIN_FAILS.shift();
}
function adminFailsLastHour() {
  const now = Date.now();
  while (ADMIN_FAILS.length && now - ADMIN_FAILS[0] > 60 * 60 * 1000) ADMIN_FAILS.shift();
  return ADMIN_FAILS.length;
}
const adminLimiter = makeLimiter(8, 15 * 60 * 1000);
const codeLimiter = makeLimiter(10, 15 * 60 * 1000);
/* كلمة المرور التي يكتبها المستخدم لفتح تشفير الملف. غيّرها في أي وقت عبر متغير بيئة
   UNLOCK_PASSPHRASE في Render — لا علاقة لها مباشرة بسرّ التشفير الفعلي، فتغييرها لا
   يكسر الأجهزة التي فتحت الملف سابقاً، ولا يحتاج إعادة بناء الملف المشفَّر إطلاقاً. */
const UNLOCK_PASSPHRASE = process.env.UNLOCK_PASSPHRASE || 'tramadool999999999999999tz';
/* السرّ الفعلي المستخدم في اشتقاق مفتاح AES الذي شُفِّر به الملف. ثابت دائماً، ولا يُرسل
   للمستخدم إلا بعد اجتياز كلمة المرور أعلاه؛ لا تُغيّره إطلاقاً إلا إذا أعدت تشفير الملف كله. */
const DECRYPT_SECRET = process.env.DECRYPT_SECRET || '4yiXvu79hyscMzPddVUGHM0PAyWKIGD7nGKKO4EbzeA';
const unlockLimiter = makeLimiter(5, 15 * 60 * 1000);

/* ---------------- الخادم (بدون مكتبات خارجية) ---------------- */
const routes = {};
function post(p, fn) { routes['POST ' + p] = fn; }
function get(p, fn) { routes['GET ' + p] = fn; }

function readBody(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on('data', (c) => {
      size += c.length;
      if (size > 600 * 1024) { reject(new Error('too large')); req.destroy(); return; }
      chunks.push(c);
    });
    req.on('end', () => {
      try { resolve(chunks.length ? JSON.parse(Buffer.concat(chunks).toString('utf8')) : {}); }
      catch (e) { reject(e); }
    });
    req.on('error', reject);
  });
}

function clientIp(req) {
  const xf = req.headers['x-forwarded-for'];
  if (xf) return String(xf).split(',')[0].trim();
  return req.socket.remoteAddress || '';
}

/* نطاقات مسموح لها فعلياً بطلب هذا الـ API من متصفح: صفحة اللوحة نفسها، وتطبيق
   المستخدمين المعبّأ عبر Capacitor (أصله الافتراضي https://localhost على أندرويد
   وcapacitor://localhost على iOS). أي طلب يملك المفتاح أو الرمز الصحيح يبقى محمياً
   بغض النظر عن CORS، لكن هذا يمنع أي موقع آخر من قراءة الردود من متصفح الضحية. */
const ALLOWED_ORIGINS = new Set([
  'https://sudanese-mafia-server.onrender.com',
  'https://sudanese-mafia-server-1.onrender.com',
  'https://localhost',
  'capacitor://localhost'
]);
const server = http.createServer(async (req, res) => {
  const origin = req.headers.origin;
  if (origin && ALLOWED_ORIGINS.has(origin)) res.setHeader('Access-Control-Allow-Origin', origin);
  res.setHeader('Vary', 'Origin');
  res.setHeader('Access-Control-Allow-Methods', 'POST, GET, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  res.setHeader('Cache-Control', 'no-store');

  const send = (status, obj) => {
    const out = JSON.stringify(obj);
    res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(out) });
    res.end(out);
  };
  if (req.method === 'OPTIONS') { res.writeHead(204); return res.end(); }

  const pathname = (req.url || '/').split('?')[0];
  const handler = routes[req.method + ' ' + pathname];
  if (!handler) return send(404, { ok: false, message: 'غير موجود' });

  let body = {};
  if (req.method === 'POST') {
    try { body = await readBody(req); }
    catch (e) { return send(400, { ok: false, message: 'طلب غير صالح' }); }
  }
  try {
    const html = (text) => {
      res.writeHead(200, {
        'Content-Type': 'text/html; charset=utf-8',
        'Content-Length': Buffer.byteLength(text),
        'X-Robots-Tag': 'noindex, nofollow',
        'X-Content-Type-Options': 'nosniff',
        'Referrer-Policy': 'no-referrer'
      });
      res.end(text);
    };
    await handler({ body, ip: clientIp(req), query: Object.fromEntries(new URL(req.url || '/', 'http://x').searchParams) }, {
      status(c) { return { json: (o) => send(c, o) }; },
      json: (o) => send(200, o),
      html,
      raw: (type, text) => { res.writeHead(200, { 'Content-Type': type, 'Content-Length': Buffer.byteLength(text) }); res.end(text); }
    });
  } catch (e) {
    console.error('handler error', e);
    send(500, { ok: false, message: 'خطأ في السيرفر' });
  }
});

