/* ---- التطبيق: التحقق من الرمز + المزامنة المباشرة ----
   نفس المسار يخدم الدخول الأول والمزامنة الدورية (التطبيق يستدعيه كل بضع ثوانٍ).
   لا يُرسل التطبيق أي محتوى خاص: فقط الرمز ومعرّف الجهاز ورقم الإصدار.
   الرد: { ok, reason, message, msg_id }
     reason: bad_code | disabled | expired | device | app_off | version | busy | bad_request */
post('/api/check', async (req, res) => {
  const ip = req.ip;
  const body = req.body || {};
  const code = normCode(body.code);
  const device = str(body.device, 100).trim();
  const version = str(body.version, 20);
  const no = (reason, message) => res.json({ ok: false, reason, message });

  if (body.preview_token) {   // فتح التطبيق من اللوحة: لا ربط جهاز ولا حظر
    const exp = PREVIEW.get(String(body.preview_token));
    if (!exp || exp < Date.now()) return no('bad_request', 'انتهت المعاينة');
    const pl = STATE.licenses[code];
    // معاينة موثّقة أصلاً بمفتاح الإدارة: نزوّد سرّ فك التشفير الفعلي تلقائياً، فلا تظهر شاشة كلمة المرور إطلاقاً هنا.
    return res.json(Object.assign({ ok: true, preview: true, message: '', msg_id: '', settings: (pl && pl.settings) || {}, unlock_pass: DECRYPT_SECRET }, pl ? syncData(code, body, pl) : {}));
  }

  if (codeLimiter.blocked(ip)) return no('busy', 'محاولات كثيرة خاطئة، حاول لاحقاً');
  if (!code || !device) return no('bad_request', 'بيانات ناقصة');

  const cfg = STATE.config;
  if (cfg.enabled === false) return no('app_off', cfg.message || 'التطبيق متوقف حالياً');
  if (cfg.min_version && cmpVersion(version, cfg.min_version) < 0) {
    return no('version', 'يرجى تحديث التطبيق إلى آخر إصدار');
  }

  const lic = STATE.licenses[code];
  if (!lic) {
    codeLimiter.fail(ip);
    await failDelay();
    return no('bad_code', 'الرمز غير صحيح');
  }
  if (lic.enabled === false) return no('disabled', lic.message || 'تم إيقاف هذا الرمز');
  if (lic.expires && Date.now() > lic.expires) return no('expired', 'انتهت صلاحية هذا الرمز');

  try {
    if (!lic.device) {
      // أول استخدام: ربط الرمز بهذا الجهاز
      await mutate((s) => {
        const l = s.licenses[code];
        if (l && !l.device) { l.device = device; l.first_used = Date.now(); }
      });
    } else if (lic.device !== device) {
      return no('device', 'هذا الرمز مرتبط بجهاز آخر');
    }
    // آخر ظهور (لا نكتب في القاعدة كل مرة، فقط عند مرور 10 دقائق أو تغيّر الإصدار)
    const now = Date.now();
    if (!lic.last_seen || now - lic.last_seen > 10 * 60 * 1000 || lic.version !== version) {
      await mutate((s) => {
        const l = s.licenses[code];
        if (l) { l.last_seen = now; l.version = version; }
      });
    }
  } catch (e) {
    console.error('check save error', e);
    return res.status(500).json({ ok: false, reason: 'server', message: 'خطأ في السيرفر، حاول مرة أخرى' });
  }

  codeLimiter.reset(ip);
  PINGS.set(code, Date.now());
  // رسالة المستخدم الخاصة لها الأولوية على الرسالة العامة
  let message = '', mid = '';
  if (lic.message) { message = lic.message; mid = msgId('u' + code, lic.message, lic.msg_ts); }
  else if (cfg.message) { message = cfg.message; mid = msgId('g', cfg.message, cfg.msg_ts); }
  res.json(Object.assign({ ok: true, message, msg_id: mid, settings: lic.settings || {} }, syncData(code, body, lic)));
});

/* ---- فتح تشفير ملف التطبيق (طبقة قبل الرمز) ---- */
post('/api/unlock', async (req, res) => {
  const ip = req.ip;
  const body = req.body || {};
  if (unlockLimiter.blocked(ip)) {
    return res.status(429).json({ ok: false, message: 'محاولات كثيرة، انتظر 15 دقيقة' });
  }
  const pass = str(body.pass, 200);
  if (!pass || !safeEqual(pass, UNLOCK_PASSPHRASE)) {
    unlockLimiter.fail(ip);
    await failDelay();
    return res.status(401).json({ ok: false, message: 'كلمة المرور غير صحيحة' });
  }
  unlockLimiter.reset(ip);
  await mutate((s) => logAction(s, 'فتح تشفير التطبيق', '-', ip));
  res.json({ ok: true, secret: DECRYPT_SECRET });
});

/* ---- تشفير ملف التطبيق: طلب فك / أمر قفل ----
   مفتاح AES الفعلي يُقرأ من متغير البيئة APP_KEY (base64) ولا يُكتب في الكود. */
const APP_KEY = process.env.APP_KEY || '';
const encLimiter = makeLimiter(30, 15 * 60 * 1000);
const devId = (v) => str(v, 80).replace(/[^A-Za-z0-9\-_]/g, '');

post('/api/decrypt-request', async (req, res) => {
  const id = devId(req.body && req.body.deviceId);
  if (id.length < 8) return res.status(400).json({ ok: false, message: 'طلب غير صالح' });
  const about = str(req.body.about, 300).trim();
  if (!about) return res.json({ ok: false, message: 'اكتب وصفاً أولاً' });
  const dev = (req.body && req.body.device && typeof req.body.device === 'object') ? req.body.device : {};
  const deviceInfo = {
    os: str(dev.os, 40), browser: str(dev.browser, 40), lang: str(dev.lang, 40),
    screen: str(dev.screen, 20), tz: str(dev.tz, 40), conn: str(dev.conn, 40)
  };
  if (encLimiter.blocked(req.ip)) return res.status(429).json({ ok: false, message: 'محاولات كثيرة' });
  encLimiter.fail(req.ip);
  const APPEAL_MAX = 3;
  let outcome = { ok: true };
  await mutate((s) => {
    if (!s.encDevices) s.encDevices = {};
    if (!s.encDevices[id] && Object.keys(s.encDevices).length >= 500) { outcome = { ok: false, message: 'تعذر الإرسال' }; return; }
    const cur = s.encDevices[id];
    if (cur && (cur.status === 'pending' || cur.status === 'denied')) { outcome = { ok: true }; return; }
    const wasLocked = !!(cur && cur.everLocked);
    const note = (cur && cur.note) || '';
    let appealCount = (cur && cur.appealCount) || 0;
    if (wasLocked) {
      if (appealCount >= APPEAL_MAX) {
        outcome = { ok: false, capped: true, message: 'تجاوزت الحد الأقصى لعدد الرسائل (٣). لن يُقبل المزيد حتى تراجعك الإدارة.' };
        return;
      }
      appealCount += 1;
    }
    s.encDevices[id] = { status: 'pending', ts: Date.now(), ip: req.ip, about: about, device: deviceInfo, everLocked: wasLocked, note: note, appealCount: appealCount };
    logAction(s, wasLocked ? ('رسالة ' + appealCount + '/' + APPEAL_MAX + ' بعد الحظر') : 'طلب فك تشفير', id.slice(0, 8), req.ip);
  });
  res.json(outcome);
});

get('/api/decrypt-status', (req, res) => {
  const id = devId(req.query && req.query.deviceId);
  const d = (STATE.encDevices || {})[id];
  if (!d) return res.json({ ok: true, status: 'none', note: '' });
  if (d.status === 'approved') {
    if (!APP_KEY) return res.json({ ok: false, status: 'error', message: 'APP_KEY غير مضبوط في السيرفر', note: d.note || '' });
    return res.json({ ok: true, status: 'approved', key: APP_KEY, note: d.note || '' });
  }
  res.json({ ok: true, status: d.status, note: d.note || '' });
});

get('/api/lock-status', (req, res) => {
  const id = devId(req.query && req.query.deviceId);
  const d = (STATE.encDevices || {})[id];
  res.json({ ok: true, locked: !!(d && d.status === 'locked') });
});

/* ---- لوحة التحكم ---- */
post('/api/admin', async (req, res) => {
  const ip = req.ip;
  const body = req.body || {};

  if (adminLimiter.blocked(ip)) {
    return res.status(429).json({ ok: false, message: 'محاولات كثيرة، انتظر 15 دقيقة' });
  }
  const role = resolveRole(body.key);
  if (!role) {
    adminLimiter.fail(ip);
    noteAdminFail();
    return res.status(401).json({ ok: false, message: 'كلمة السر غير صحيحة' });
  }
  adminLimiter.reset(ip);

  const action = body.action;
  const d = body.data || {};
  const readOnlyActions = new Set(['list', 'log', 'enc_list']);
  if (role === 'viewer' && !readOnlyActions.has(action)) {
    return res.status(403).json({ ok: false, message: 'هذا الدخول للعرض فقط، لا يملك صلاحية التعديل' });
  }

  try {
    switch (action) {
      case 'list': {
        const now = Date.now();
        const licenses = Object.keys(STATE.licenses).map((code) => {
          const l = STATE.licenses[code];
          const ud = (STATE.userdata || {})[code];
          const data = {};
          SYNC_KEYS.forEach((k) => { if (ud && ud.keys && k in ud.keys) data[k] = ud.keys[k]; });
          const last_changed = (ud && ud.lastChanged) || {};
          return { code, ...l, expired: !!(l.expires && now > l.expires), online: !!(PINGS.get(code) && now - PINGS.get(code) < ONLINE_MS), data, last_changed };
        });
        licenses.sort((a, b) => (b.created || 0) - (a.created || 0));
        return res.json({ ok: true, role, config: STATE.config, licenses, shared_names: (STATE.sharedNames && STATE.sharedNames.list) || '[]', admin_fails_1h: adminFailsLastHour() });
      }

      case 'sharesave': {
        let arr;
        try { arr = JSON.parse(d.list); } catch (e) { return res.json({ ok: false, message: 'صيغة JSON غير صحيحة' }); }
        if (!Array.isArray(arr)) return res.json({ ok: false, message: 'يجب أن تكون قائمة' });
        if (arr.length > 300) return res.json({ ok: false, message: 'الحد الأقصى 300 اسم' });
        const clean = arr.filter((x) => x && x.num).map((x) => ({
          num: str(x.num, 20), name: str(x.name, 80), type: str(x.type, 40), branch: str(x.branch, 40)
        }));
        const listStr = JSON.stringify(clean);
        if (listStr.length > 60000) return res.json({ ok: false, message: 'القائمة كبيرة جداً' });
        await mutate((s) => {
          if (!s.sharedNames) s.sharedNames = { rev: 0, list: '[]' };
          s.sharedNames.list = listStr;
          s.sharedNames.rev++;
          logAction(s, 'تعديل الدليل المشترك', '(' + clean.length + ' اسم)');
        });
        return res.json({ ok: true });
      }

      case 'setdata': {
        const code = normCode(d.code);
        if (!STATE.licenses[code]) return res.json({ ok: false, message: 'الرمز غير موجود' });
        const ch = d.changes && typeof d.changes === 'object' ? d.changes : {};
        await mutate((s) => {
          if (!s.userdata) s.userdata = {};
          const ud = s.userdata[code] || (s.userdata[code] = { rev: 0, keys: {} });
          let n = 0;
          SYNC_KEYS.forEach((k) => {
            if (!(k in ch)) return;
            const v = ch[k];
            if (v === null) { if (k in ud.keys) { delete ud.keys[k]; n++; } return; }
            const sv = str(v, 100000);
            if (ud.keys[k] !== sv) { ud.keys[k] = sv; n++; }
          });
          if (n) { ud.rev++; logAction(s, 'تعديل بيانات من اللوحة', code); }
        });
        return res.json({ ok: true });
      }

      case 'cleardata': {
        const code = normCode(d.code);
        await mutate((s) => { if (s.userdata) delete s.userdata[code]; logAction(s, 'مسح بيانات المزامنة', code); });
        return res.json({ ok: true });
      }

      case 'preview': {
        const code = normCode(d.code);
        if (!STATE.licenses[code]) return res.json({ ok: false, message: 'الرمز غير موجود' });
        const now = Date.now();
        PREVIEW.forEach((v, k) => { if (v < now) PREVIEW.delete(k); });
        const token = crypto.randomBytes(16).toString('hex');
        PREVIEW.set(token, now + 30 * 60 * 1000);
        return res.json({ ok: true, token });
      }

      case 'enc_list': {
        const devs = STATE.encDevices || {};
        const list = Object.keys(devs).map((id) => Object.assign({ id }, devs[id])).sort((a, b) => (b.ts || 0) - (a.ts || 0));
        return res.json({ ok: true, devices: list, key_set: !!APP_KEY });
      }

      case 'enc_set': {
        const id = devId(d.id);
        const st = d.status;
        if (!['approved', 'denied', 'locked', 'delete'].includes(st)) return res.json({ ok: false, message: 'حالة غير معروفة' });
        if (!(STATE.encDevices || {})[id]) return res.json({ ok: false, message: 'الجهاز غير موجود' });
        await mutate((s) => {
          if (st === 'delete') delete s.encDevices[id];
          else { s.encDevices[id].status = st; s.encDevices[id].ts = Date.now(); if (st === 'locked') s.encDevices[id].everLocked = true; }
          logAction(s, 'تشفير: ' + st, id.slice(0, 8));
        });
        return res.json({ ok: true });
      }

      case 'enc_note': {
        const id = devId(d.id);
        if (!(STATE.encDevices || {})[id]) return res.json({ ok: false, message: 'الجهاز غير موجود' });
        const note = str(d.note, 300).trim();
        await mutate((s) => { s.encDevices[id].note = note; logAction(s, 'رسالة إلى جهاز', id.slice(0, 8)); });
        return res.json({ ok: true });
      }

      case 'enc_lockall': {
        await mutate((s) => {
          Object.keys(s.encDevices || {}).forEach((id) => { if (s.encDevices[id].status === 'approved') { s.encDevices[id].status = 'locked'; s.encDevices[id].ts = Date.now(); } });
          logAction(s, 'أمر تشفير لكل الأجهزة', '');
        });
        return res.json({ ok: true });
      }

      case 'log': {
        const n = Math.min(Math.max(parseInt(d.limit, 10) || 100, 1), 300);
        const log = (STATE.log || []).slice(-n).slice().reverse();
        return res.json({ ok: true, log });
      }

      case 'save': {
        const code = normCode(d.code);
        if (code.length < 6 || code.length > 40 || !/^[A-Z0-9\-_]+$/.test(code)) {
          return res.json({ ok: false, message: 'الرمز يجب أن يكون 6 أحرف على الأقل (حروف إنجليزية وأرقام و - فقط)' });
        }
        if (d.settings !== undefined && JSON.stringify(d.settings || {}).length > 2000) return res.json({ ok: false, message: 'الإعدادات كبيرة جداً' });
        if (!STATE.licenses[code] && code.length < 12) {
          return res.json({ ok: false, message: 'الرموز الجديدة يجب أن تكون 12 حرفاً على الأقل (استخدم زر توليد رمز)' });
        }
        const expires = parseExpiry(d.expires);
        await mutate((s) => {
          const old = s.licenses[code] || {};
          s.licenses[code] = {
            name: str(d.name, 80),
            enabled: d.enabled !== false,
            message: str(d.message, 300),
            sync: d.sync === undefined ? (old.sync !== false) : d.sync !== false,
            settings: (d.settings && typeof d.settings === 'object' && !Array.isArray(d.settings)) ? d.settings : (old.settings || {}),
            msg_ts: (str(d.message, 300) && (str(d.message, 300) !== (old.message || '') || d.resend === true)) ? Date.now() : (old.msg_ts || 0),
            notes: str(d.notes, 500),
            expires: expires,
            device: old.device || null,
            created: old.created || Date.now(),
            first_used: old.first_used || null,
            last_seen: old.last_seen || null,
            version: old.version || ''
          };
          logAction(s, old.created ? 'تعديل' : 'إضافة', code);
        });
        return res.json({ ok: true });
      }

      case 'reset': {
        const code = normCode(d.code);
        if (!STATE.licenses[code]) return res.json({ ok: false, message: 'الرمز غير موجود' });
        await mutate((s) => {
          if (s.licenses[code]) s.licenses[code].device = null;
          logAction(s, 'فك الجهاز', code);
        });
        return res.json({ ok: true });
      }

      case 'delete': {
        const code = normCode(d.code);
        if (!STATE.licenses[code]) return res.json({ ok: false, message: 'الرمز غير موجود' });
        await mutate((s) => { delete s.licenses[code]; logAction(s, 'حذف', code); });
        return res.json({ ok: true });
      }

      case 'bulk': {
        const op = d.op;
        const codes = Array.isArray(d.codes) ? d.codes.map(normCode).filter(Boolean).slice(0, 200) : [];
        if (!codes.length) return res.json({ ok: false, message: 'لم يُحدَّد أي مستخدم' });
        if (!['enable', 'disable', 'delete'].includes(op)) {
          return res.json({ ok: false, message: 'إجراء جماعي غير معروف' });
        }
        await mutate((s) => {
          codes.forEach((code) => {
            const l = s.licenses[code];
            if (!l) return;
            if (op === 'delete') { delete s.licenses[code]; logAction(s, 'حذف جماعي', code); }
            else { l.enabled = op === 'enable'; logAction(s, op === 'enable' ? 'تشغيل جماعي' : 'إيقاف جماعي', code); }
          });
        });
        return res.json({ ok: true });
      }

      case 'setkey': {
        const target = d.role === 'viewer' ? 'viewer' : 'admin';
        const newKey = str(d.key, 100).trim();
        if (target === 'admin') {
          if (newKey.length < 8) return res.json({ ok: false, message: 'كلمة السر يجب أن تكون 8 أحرف على الأقل' });
          await mutate((s) => { s.auth = s.auth || {}; s.auth.adminKey = newKey; logAction(s, 'تغيير كلمة سر الإدارة', ''); });
        } else {
          if (newKey && newKey.length < 8) return res.json({ ok: false, message: 'كلمة السر يجب أن تكون 8 أحرف على الأقل، أو اتركها فارغة للتعطيل' });
          await mutate((s) => { s.auth = s.auth || {}; s.auth.viewerKey = newKey; logAction(s, newKey ? 'تغيير كلمة سر العرض' : 'تعطيل دخول العرض', ''); });
        }
        return res.json({ ok: true });
      }

      case 'config': {
        await mutate((s) => {
          const oldC = s.config || {};
          const newMsg = str(d.message, 300);
          s.config = {
            enabled: d.enabled !== false,
            message: newMsg,
            msg_ts: (newMsg && (newMsg !== (oldC.message || '') || d.resend === true)) ? Date.now() : (oldC.msg_ts || 0),
            min_version: str(d.min_version, 20).trim()
          };
          logAction(s, 'تعديل الإعدادات العامة', '');
        });
        return res.json({ ok: true });
      }

      default:
        return res.json({ ok: false, message: 'إجراء غير معروف' });
    }
  } catch (e) {
    console.error('admin error', e);
    return res.status(500).json({ ok: false, message: 'خطأ في السيرفر' });
  }
});

/* ---------------- التشغيل ---------------- */
(async () => {
  await store.init();
  const loaded = await store.load();
  if (loaded) {
    STATE = {
      config: Object.assign(DEFAULT_STATE().config, loaded.config || {}),
      licenses: loaded.licenses || {},
      log: Array.isArray(loaded.log) ? loaded.log : [],
      auth: loaded.auth && typeof loaded.auth === 'object' ? loaded.auth : { adminKey: null, viewerKey: null },
      userdata: loaded.userdata && typeof loaded.userdata === 'object' ? loaded.userdata : {},
      sharedNames: loaded.sharedNames && typeof loaded.sharedNames === 'object' ? loaded.sharedNames : { rev: 0, list: '[]' },
      encDevices: loaded.encDevices && typeof loaded.encDevices === 'object' ? loaded.encDevices : {}
    };
  } else {
    await store.save(STATE);
  }
  const port = process.env.PORT || 3000;
  server.listen(port, () => console.log('server on :' + port + ' storage=' + store.kind));
})().catch((e) => { console.error(e); process.exit(1); });
